-- FIG WAG 2025-2028 element seed for GymTrack.
-- Run supabase/fig_elite_schema.sql first, then this file.
-- Extracted from the uploaded FIG WAG COP 2025-2028 table sections: VT p.59-69, UB p.71-106, BB p.107-147, FX p.148-169.

on conflict (id) do update set
  apparatus=excluded.apparatus, code=excluded.code, name=excluded.name, element_group=excluded.element_group,
  value_letter=excluded.value_letter, dv=excluded.dv, tags=excluded.tags, note=excluded.note;
